      "El equipo administrativo está evaluando tu documentación. Recibirás una notificación cuando se emita el dictamen. Tu nombre no aparecerá en el tarjetón de votación hasta recibir aprobación.": "Das Verwaltungsteam prüft Ihre Unterlagen. Sie werden benachrichtigt, sobald ein Entscheid vorliegt. Ihr Name erscheint erst nach Genehmigung auf dem Stimmzettel.",
      "El estudiante completará su propio auto-registro, eligiendo su correo y contraseña personal.": "Der Schüler schließt seine eigene Selbstregistrierung ab und wählt dabei seine persönliche E-Mail-Adresse und sein Passwort.",
