      "Sign In": "ログイン",
      "Help Assistant": "ヘルプアシスタント",
      "Online (Automatic)": "オンライン（自動）",
      "Ingresa tu número de documento en Crear mi cuenta. Si el colegio ya te habilitó en la lista de estudiantes autorizados, verás tu nombre y grado precargados; solo debes definir tu correo de contacto y una contraseña (mínimo 8 caracteres, una mayúscula y un símbolo especial). Si el sistema no reconoce tu documento, contacta al Administrador del colegio.": "アカウント作成で学籍番号または身分証番号を入力してください。学校が許可済み学生名簿であなたを有効化している場合、氏名と学年が入力されます。連絡先メールアドレスとパスワード（8文字以上、大文字1文字、特殊記号1つ）を設定してください。システムが番号を認識しない場合は学校の管理者に連絡してください。",
      "Ingresa tu número de documento y la contraseña que tú mismo definiste al crear tu cuenta. El sistema nunca te envía la contraseña por correo al registrarte: solo lo hace si usas la opción Recuperar acceso. Si los datos no coinciden, revisa que no haya espacios de más en el documento.": "学籍番号または身分証番号と、アカウント作成時に自分で設定したパスワードを入力してください。登録時にパスワードがメールで送られることはありません。アクセス復旧を使用した場合のみ送信されます。情報が一致しない場合は、番号に余分な空白がないか確認してください。",
      "Ve a Recuperar acceso e ingresa tu documento. Te enviaremos una nueva contraseña al correo de contacto que registraste al crear tu cuenta.": "アクセス復旧に移動して番号を入力してください。アカウント作成時に登録した連絡先メールアドレスへ新しいパスワードを送信します。",
      "Durante la etapa de Inscripción de una elección, entra a Postularme como candidato, carga tu foto, tus propuestas y tu plan de gobierno, además de los documentos que exija el cargo al que aspiras. Tu postulación queda pendiente hasta que el Administrador la revise y apruebe; solo entonces aparecerás en el tarjetón.": "選挙の登録期間中に候補者として応募し、写真、提案、施政計画、および役職に必要な書類をアップロードしてください。申請は管理者が審査・承認するまで保留され、承認後に投票用紙へ表示されます。",
      "Cuando la elección esté en su etapa de Votación, elige un candidato en el tarjetón, revisa sus propuestas en la ventana emergente y confirma tu voto. Una vez confirmado, no se puede deshacer.": "選挙の投票期間中に投票用紙から候補者を選び、ポップアップで提案を確認して投票を確定してください。確定後は取り消せません。",
      "Puedes cambiar tu correo de contacto o tu contraseña desde Mi perfil. Tu documento, nombre y grado los administra el colegio y no se pueden editar.": "連絡先メールアドレスやパスワードはプロフィールから変更できます。番号、氏名、学年は学校が管理しているため変更できません。",
      "Entiendo que la información no fue suficiente para resolver tu duda. Puedes formular otra pregunta o radicar una solicitud formal:": "情報だけでは疑問を解決できなかったことを理解しました。別の質問を入力するか、正式な申請を行えます：",
      "No encontré una respuesta directa para tu búsqueda. Puedes elegir un tema del menú o radicar una solicitud formal para que un administrador te responda:": "検索に対する直接の回答が見つかりませんでした。メニューからトピックを選ぶか、管理者への正式な申請を行ってください：",
      "¡Me alegra haberte ayudado!": "お役に立ててうれしいです！",
      "Si tienes otra consulta, escribe una palabra clave o selecciona un tema del menú inferior.": "別の質問がある場合はキーワードを入力するか、下のメニューからトピックを選択してください。",
      "Sí, resolvió mi duda.": "はい、疑問が解決しました。",
      "No resolvió mi duda.": "いいえ、疑問は解決しませんでした。",
      "Por seguridad, debes confirmar tu contraseña actual antes de cambiar el correo. Se enviará un aviso a tu dirección anterior.": "セキュリティのため、メールアドレスを変更する前に現在のパスワードを確認する必要があります。以前のアドレスに通知が送信されます。",
      "Debes ingresar tu contraseña actual.": "現在のパスワードを入力してください。",
      "Error de conexión. Verifica tu red e intenta de nuevo.": "接続エラーです。ネットワークを確認して、もう一度お試しください。",
      "La contraseña actual no es correcta.": "現在のパスワードが正しくありません。",
      "La contraseña actual no coincide.": "現在のパスワードが一致しません。",
      "Debes ingresar tu contraseña actual para modificar el correo de contacto.": "連絡先メールアドレスを変更するには、現在のパスワードを入力してください。",
      "Correo actualizado. El aviso de seguridad a tu correo anterior no pudo enviarse, pero el cambio quedó guardado.": "メールアドレスを更新しました。以前のメールアドレスへのセキュリティ通知は送信できませんでしたが、変更は保存されました。",
