      "El usuario puede solicitar una nueva recuperación de acceso.": "用户可以重新申请访问恢复。",
      "Para obtener una nueva contraseña, usa “Recuperar acceso”.": "如需获取新密码，请使用“恢复访问”。",
      "El correo no existe o ya no se puede reintentar manualmente.": "未找到邮件记录，或该邮件已无法手动重试。",
