      "Cómo votar": "如何投票",
      "Postulación": "申请",
      "Mi perfil": "我的资料",
      "Sign In": "登录",
      "Help Assistant": "帮助助手",
      "Online (Automatic)": "在线（自动）",
      "Ingresa tu número de documento en Crear mi cuenta. Si el colegio ya te habilitó en la lista de estudiantes autorizados, verás tu nombre y grado precargados; solo debes definir tu correo de contacto y una contraseña (mínimo 8 caracteres, una mayúscula y un símbolo especial). Si el sistema no reconoce tu documento, contacta al Administrador del colegio.": "在创建账户中输入您的证件号码。如果学校已在授权学生名册中启用您，系统会预填您的姓名和年级；您只需设置联系邮箱和密码（至少8个字符、包含一个大写字母和一个特殊符号）。如果系统无法识别您的证件号码，请联系学校管理员。",
      "Ingresa tu número de documento y la contraseña que tú mismo definiste al crear tu cuenta. El sistema nunca te envía la contraseña por correo al registrarte: solo lo hace si usas la opción Recuperar acceso. Si los datos no coinciden, revisa que no haya espacios de más en el documento.": "请输入您的证件号码和创建账户时自行设置的密码。注册时系统不会通过邮件发送密码，只有使用访问权限找回功能时才会发送。如果信息不匹配，请检查证件号码中是否有多余空格。",
      "Ve a Recuperar acceso e ingresa tu documento. Te enviaremos una nueva contraseña al correo de contacto que registraste al crear tu cuenta.": "进入访问权限找回并输入您的证件号码。我们会将新密码发送到您创建账户时登记的联系邮箱。",
      "Durante la etapa de Inscripción de una elección, entra a Postularme como candidato, carga tu foto, tus propuestas y tu plan de gobierno, además de los documentos que exija el cargo al que aspiras. Tu postulación queda pendiente hasta que el Administrador la revise y apruebe; solo entonces aparecerás en el tarjetón.": "在选举报名阶段，进入报名参选候选人，上传您的照片、提案、施政计划以及职位要求的文件。您的报名将在管理员审核批准前保持待处理状态，批准后才会显示在选票上。",
      "Cuando la elección esté en su etapa de Votación, elige un candidato en el tarjetón, revisa sus propuestas en la ventana emergente y confirma tu voto. Una vez confirmado, no se puede deshacer.": "选举进入投票阶段后，请在选票上选择候选人，在弹窗中查看其提案并确认投票。确认后无法撤销。",
      "Puedes cambiar tu correo de contacto o tu contraseña desde Mi perfil. Tu documento, nombre y grado los administra el colegio y no se pueden editar.": "您可以在个人资料中修改联系邮箱或密码。您的证件号码、姓名和年级由学校管理，无法编辑。",
      "Entiendo que la información no fue suficiente para resolver tu duda. Puedes formular otra pregunta o radicar una solicitud formal:": "我明白这些信息不足以解决您的疑问。您可以提出其他问题或提交正式申请：",
      "No encontré una respuesta directa para tu búsqueda. Puedes elegir un tema del menú o radicar una solicitud formal para que un administrador te responda:": "未找到与您搜索内容直接对应的答案。您可以从菜单选择主题，或提交正式申请让管理员回复：",
      "¡Me alegra haberte ayudado!": "很高兴能帮到您！",
      "Si tienes otra consulta, escribe una palabra clave o selecciona un tema del menú inferior.": "如有其他问题，请输入关键词或从下方菜单选择主题。",
      "Sí, resolvió mi duda.": "是的，我的问题解决了。",
      "No resolvió mi duda.": "没有解决我的问题。",
      "Por seguridad, debes confirmar tu contraseña actual antes de cambiar el correo. Se enviará un aviso a tu dirección anterior.": "出于安全考虑，更改邮箱前需要先确认您的当前密码。系统将向您之前的邮箱地址发送通知。",
      "Debes ingresar tu contraseña actual.": "请输入您的当前密码。",
      "Error de conexión. Verifica tu red e intenta de nuevo.": "连接错误。请检查网络后重试。",
      "La contraseña actual no es correcta.": "当前密码不正确。",
      "La contraseña actual no coincide.": "当前密码不匹配。",
      "Debes ingresar tu contraseña actual para modificar el correo de contacto.": "请输入当前密码以修改联系邮箱。",
      "Correo actualizado. El aviso de seguridad a tu correo anterior no pudo enviarse, pero el cambio quedó guardado.": "邮箱已更新。发送到您原邮箱的安全通知未能送出，但更改已保存。",
      "Código de verificación": "验证码",
